<?php
require_once __DIR__.'/Producto.php';require_once __DIR__.'/../Services/Auditoria.php';
class BorradorVenta {
 private $db;
 public function __construct(PDO $db){$this->db=$db;}
 public static function uuid($v){if(!is_string($v)||!preg_match('/^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/D',$v))throw new HttpError('El identificador del ticket no es válido.');return $v;}
 private function version($d){$v=isset($d['version'])?$d['version']:null;if(!is_scalar($v)||!preg_match('/^(0|[1-9][0-9]{0,17})$/D',(string)$v))throw new HttpError('Actualiza el ticket antes de guardar.');return (string)$v;}
 private static function text($v,$max){if(!is_string($v)||strlen($v)>$max)throw new HttpError('El ticket contiene un texto demasiado largo o no válido.');return $v;}
 private static function scalarText($v,$max){if(!is_scalar($v)&&$v!==null)throw new HttpError('El ticket contiene un valor no válido.');return self::text($v===null?'':(string)$v,$max);}
 public static function contenido(array $d){
  if(!isset($d['venta'])||!is_array($d['venta']))throw new HttpError('Faltan los datos del ticket.');$v=$d['venta'];$turn=Producto::identificador(isset($v['turno_id'])?$v['turno_id']:null);$client=Producto::identificador(isset($v['cliente_id'])?$v['cliente_id']:null,true);
  $lines=isset($v['detalles'])?$v['detalles']:null;if(!is_array($lines)||count($lines)>100)throw new HttpError('El ticket admite hasta 100 variantes.');$out=array();$ids=array();foreach($lines as $line){if(!is_array($line))throw new HttpError('Un renglón del ticket no es válido.');$id=Producto::identificador(isset($line['variante_id'])?$line['variante_id']:null);if(isset($ids[$id]))throw new HttpError('Una variante aparece repetida.');$ids[$id]=true;$x=array('variante_id'=>$id);foreach(array('cantidad','precio_unitario','descuento') as $k)$x[$k]=self::scalarText(isset($line[$k])?$line[$k]:'',32);$out[]=$x;}
  $items=isset($d['productos'])?$d['productos']:array();if(!is_array($items)||count($items)>100)throw new HttpError('Los datos de productos no son válidos.');$products=array();foreach($items as $p){if(!is_array($p))throw new HttpError('Producto no válido.');$x=array('id'=>Producto::identificador(isset($p['id'])?$p['id']:null));foreach(array('producto_nombre'=>800,'variante_nombre'=>800,'sku'=>256,'unidad_codigo'=>80,'precio'=>32,'existencia'=>32) as $k=>$max)$x[$k]=self::scalarText(isset($p[$k])?$p[$k]:'',$max);foreach(array('permite_decimales','controla_inventario') as $k)$x[$k]=empty($p[$k])?0:1;$products[]=$x;}
  $pays=isset($d['pagos'])?$d['pagos']:array();if(!is_array($pays)||count($pays)>8)throw new HttpError('El ticket admite hasta ocho métodos de pago.');$payments=array();foreach($pays as $p){if(!is_array($p))throw new HttpError('Pago preparado no válido.');$x=array('metodo_pago_id'=>isset($p['metodo_pago_id'])&&$p['metodo_pago_id']!==''?Producto::identificador($p['metodo_pago_id']):'');foreach(array('monto'=>32,'recibido'=>32,'referencia'=>400) as $k=>$max)$x[$k]=self::scalarText(isset($p[$k])?$p[$k]:'',$max);$x['auto']=!empty($p['auto']);$payments[]=$x;}
  return array('venta'=>array('turno_id'=>$turn,'cliente_id'=>$client,'cliente_nombre'=>self::text(isset($v['cliente_nombre'])?$v['cliente_nombre']:'',800),'notas'=>self::text(isset($v['notas'])?$v['notas']:'',2000),'detalles'=>$out),'productos'=>$products,'pagos'=>$payments,'cliente_tocado'=>!empty($d['cliente_tocado']));
 }
 private function actor($id,$selling=false){$this->db->query('SELECT id FROM roles ORDER BY id FOR SHARE')->fetchAll();$q=$this->db->prepare('SELECT id FROM usuarios WHERE id=? FOR SHARE');$q->execute(array($id));$q->fetchColumn();$a=(new Usuario($this->db))->buscar($id);if(!$a||!$a['activo']||(empty($a['permisos']['todo'])&&empty($a['permisos']['vender'])&&($selling||empty($a['permisos']['ver_ventas']))))throw new HttpError('No tienes permiso para acceder a tickets pendientes.',403);return $a;}
 private function lockTurn($id){$q=$this->db->prepare('SELECT caja_id FROM turnos_caja WHERE id=?');$q->execute(array($id));$box=$q->fetchColumn();if(!$box)throw new HttpError('Turno no encontrado.',404);$q=$this->db->prepare('SELECT activo,ubicacion_id FROM cajas WHERE id=? FOR UPDATE');$q->execute(array($box));$b=$q->fetch();$q=$this->db->prepare('SELECT id,abierto_por,estatus,ubicacion_id FROM turnos_caja WHERE id=? FOR UPDATE');$q->execute(array($id));$t=$q->fetch();$q=$this->db->prepare('SELECT activo,disponible_venta FROM ubicaciones WHERE id=? FOR SHARE');$q->execute(array($t['ubicacion_id']===null?$b['ubicacion_id']:$t['ubicacion_id']));$l=$q->fetch();$t['habilitado']=$b&&$b['activo']&&$l&&$l['activo']&&$l['disponible_venta'];return $t;}

 private function row($id,$lock=false){$q=$this->db->prepare('SELECT *,UNIX_TIMESTAMP(actualizado_en) actualizado_unix FROM borradores_venta WHERE id=?'.($lock?' FOR UPDATE':''));$q->execute(array(self::uuid($id)));return $q->fetch();}
 private function access(array $r,array $a,$own=false){if((string)$r['usuario_id']!==(string)$a['id']&&($own||empty($a['permisos']['todo'])))throw new HttpError('Solo puedes recuperar y cobrar tus propios tickets pendientes.',403);}
 private function dto(array $r){unset($r['huella'],$r['solicitud'],$r['creado_en'],$r['actualizado_en']);$r['contenido']=json_decode($r['contenido'],true);$r['cobro']=$r['cobro']?json_decode($r['cobro'],true):null;if($r['venta_id']){$q=$this->db->prepare('SELECT id venta_id,folio,total FROM ventas WHERE id=?');$q->execute(array($r['venta_id']));$r['venta']=$q->fetch();}return $r;}
 public function listar(array $a,array $f){$all=isset($f['todos'])&&$f['todos']==='1';if($all&&empty($a['permisos']['todo']))throw new HttpError('Solo el administrador consulta tickets de otros usuarios.',403);$args=array();$where="d.estado IN ('en_curso','espera','cobrando')";if(!$all){$where.=' AND d.usuario_id=?';$args[]=$a['id'];}if(isset($f['antes_de'])&&$f['antes_de']!==''){if(!is_string($f['antes_de'])||strlen($f['antes_de'])>512)throw new HttpError('Página de pendientes no válida.');$cursor=json_decode(base64_decode($f['antes_de'],true),true);if(!is_array($cursor)||!isset($cursor['time'],$cursor['id'])||!is_int($cursor['time']))throw new HttpError('Página de pendientes no válida.');self::uuid($cursor['id']);$where.=' AND (d.actualizado_en<FROM_UNIXTIME(?) OR (d.actualizado_en=FROM_UNIXTIME(?) AND d.id<?))';array_push($args,$cursor['time'],$cursor['time'],$cursor['id']);}$sql='SELECT d.id,d.usuario_id,d.turno_id,d.estado,d.version,UNIX_TIMESTAMP(d.actualizado_en) actualizado_unix,u.nombre usuario,c.nombre caja,t.estatus turno_estado,JSON_UNQUOTE(JSON_EXTRACT(d.contenido,\'$.venta.cliente_nombre\')) cliente,JSON_LENGTH(JSON_EXTRACT(d.contenido,\'$.venta.detalles\')) renglones FROM borradores_venta d JOIN usuarios u ON u.id=d.usuario_id JOIN turnos_caja t ON t.id=d.turno_id JOIN cajas c ON c.id=t.caja_id WHERE '.$where.' ORDER BY d.actualizado_en DESC,d.id DESC LIMIT 31';$q=$this->db->prepare($sql);$q->execute($args);$rows=$q->fetchAll();$more=count($rows)>30;if($more)array_pop($rows);$last=$rows?end($rows):null;return array('tickets'=>$rows,'siguiente'=>$more?base64_encode(json_encode(array('time'=>(int)$last['actualizado_unix'],'id'=>$last['id']))):null,'todos'=>$all,'epoch'=>Auth::epoch());}
 public function obtener($id,array $a){$r=$this->row($id);if(!$r)throw new HttpError('Ticket pendiente no encontrado.',404);$this->access($r,$a);return $this->dto($r);}
 public function guardar($id,array $d,$actorId){$id=self::uuid($id);$version=$this->version($d);$token=self::uuid(isset($d['solicitud'])?$d['solicitud']:null);$content=self::contenido(isset($d['contenido'])&&is_array($d['contenido'])?$d['contenido']:array());$state=isset($d['estado'])?$d['estado']:'en_curso';if(!in_array($state,array('en_curso','espera'),true))throw new HttpError('Estado de ticket no válido.');$json=json_encode($content,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);if($json===false||strlen($json)>131072)throw new HttpError('El ticket supera el tamaño de guardado.');$hash=hash('sha256',$json.':'.$state);
  $this->db->beginTransaction();try{$a=$this->actor($actorId,true);$t=$this->lockTurn($content['venta']['turno_id']);if((string)$t['abierto_por']!==(string)$actorId)throw new HttpError('Guarda el ticket en tu propio turno.',403);if($t['estatus']!=='abierto'||!$t['habilitado'])throw new HttpError('La caja o su ubicación ya no están disponibles.',409);$r=$this->row($id,true);if($r){$this->access($r,$a,true);if((string)$r['turno_id']!==$content['venta']['turno_id'])throw new HttpError('El ticket pertenece a otra caja.',409);if(in_array($r['estado'],array('cobrando','cobrado','descartado'),true))throw new HttpError('El ticket cambió de estado. Consulta sus pendientes antes de continuar.',409);if(hash_equals($r['solicitud'],$token)){if(!hash_equals($r['huella'],$hash))throw new HttpError('La solicitud de guardado cambió.',409);$this->db->commit();return $this->obtener($id,$a);}if((string)$r['version']!==$version)throw new HttpError('Este ticket fue modificado en otra pestaña. Recupera la versión guardada o conserva tu copia como otro ticket.',409);$this->db->prepare('UPDATE borradores_venta SET contenido=?,estado=?,version=version+1,solicitud=?,huella=?,actualizado_en=CURRENT_TIMESTAMP WHERE id=?')->execute(array($json,$state,$token,$hash,$id));}else{if($version!=='0')throw new HttpError('El ticket no existe. Conserva su copia local como un ticket nuevo.',409);$this->db->prepare('INSERT INTO borradores_venta(id,usuario_id,turno_id,contenido,estado,solicitud,huella) VALUES(?,?,?,?,?,?,?)')->execute(array($id,$actorId,$t['id'],$json,$state,$token,$hash));}if($state==='espera'&&(!$r||$r['estado']!=='espera'))Auditoria::registrar($this->db,$actorId,'ticket_en_espera','Pendiente '.substr($id,0,8),'Ticket sin cobrar',null,array('estado'=>'espera','renglones'=>count($content['venta']['detalles'])));$this->db->commit();return $this->obtener($id,$a);}catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}}
 private static function canonical($v){if(!is_array($v))return $v;if(array_keys($v)!==range(0,count($v)-1))ksort($v);foreach($v as &$item)$item=self::canonical($item);unset($item);return $v;}
 private static function same($a,$b){return self::canonical($a)===self::canonical($b);}
 public static function datosCobro(array $d){$out=array();foreach(array('turno_id','cliente_id','cliente_nombre','notas','detalles','pagos','sello','clave','borrador_id','borrador_version') as $k)if(array_key_exists($k,$d))$out[$k]=$d[$k];return $out;}
 public function preparar($id,array $d,$actorId){$version=$this->version($d);$data=isset($d['cobro'])&&is_array($d['cobro'])?$d['cobro']:array();self::uuid(isset($data['clave'])?$data['clave']:null);if(!isset($data['sello'])||!is_string($data['sello'])||!preg_match('/^[a-f0-9]{64}$/D',$data['sello']))throw new HttpError('Calcula el ticket antes de preparar el cobro.');$content=self::contenido(array('venta'=>$data,'pagos'=>isset($data['pagos'])?$data['pagos']:array()));if(!$content['venta']['detalles'])throw new HttpError('Agrega productos antes de cobrar.');$data=self::datosCobro($data);unset($data['borrador_id'],$data['borrador_version']);if(strlen(json_encode($data))>131072)throw new HttpError('Cobro demasiado grande.');
  $this->db->beginTransaction();try{$a=$this->actor($actorId,true);$t=$this->lockTurn($content['venta']['turno_id']);$r=$this->row($id,true);if(!$r)throw new HttpError('Guarda el ticket antes de cobrar.',409);$this->access($r,$a,true);if((string)$r['turno_id']!==$content['venta']['turno_id'])throw new HttpError('El ticket pertenece a otra caja.',409);if($r['estado']==='cobrando'){$old=json_decode($r['cobro'],true);$same=$old;unset($same['borrador_id'],$same['borrador_version']);if(!self::same($same,$data))throw new HttpError('Hay un cobro pendiente de resolver. Reintenta ese mismo cobro.',409);$this->db->commit();return $this->obtener($id,$a);}if(!in_array($r['estado'],array('en_curso','espera'),true)||(string)$r['version']!==$version)throw new HttpError('El ticket cambió. Consulta sus pendientes.',409);if($t['estatus']!=='abierto'||!$t['habilitado']||(string)$t['abierto_por']!==(string)$actorId)throw new HttpError('Necesitas tu propio turno habilitado para cobrar.',409);$saved=json_decode($r['contenido'],true);if(!self::same($saved['venta'],$content['venta']))throw new HttpError('El ticket cambió durante el guardado. Vuelve a revisar los importes.',409);$data['borrador_id']=$r['id'];$data['borrador_version']=(int)$r['version']+1;$this->db->prepare("UPDATE borradores_venta SET estado='cobrando',cobro=?,version=version+1,actualizado_en=CURRENT_TIMESTAMP WHERE id=?")->execute(array(json_encode($data),$id));$this->db->commit();return $this->obtener($id,$a);}catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}}
 public function terminar($id,array $d,$actorId,$discard){$version=$this->version($d);$reason=Producto::texto($d,'motivo',300,$discard);$first=$this->row($id);if(!$first)throw new HttpError('Ticket pendiente no encontrado.',404);$this->db->beginTransaction();try{$a=$this->actor($actorId);$this->lockTurn($first['turno_id']);$r=$this->row($id,true);$this->access($r,$a);if($r['estado']==='cobrado'){$this->db->commit();return $this->obtener($id,$a);}if($r['estado']==='descartado'){$this->db->commit();return $this->obtener($id,$a);}if((string)$r['version']!==$version)throw new HttpError('El ticket cambió. Actualiza antes de descartarlo o revisar su cobro.',409);$state=$discard?'descartado':'en_curso';$this->db->prepare('UPDATE borradores_venta SET estado=?,cobro=NULL,version=version+1,actualizado_en=CURRENT_TIMESTAMP WHERE id=?')->execute(array($state,$id));if($discard)Auditoria::registrar($this->db,$actorId,'ticket_descartado','Pendiente '.substr($id,0,8),'Se descartó un ticket sin cobrar',array('estado'=>$r['estado']),array('estado'=>$state),array('motivo'=>$reason,'propietario_id'=>$r['usuario_id']));$this->db->commit();return $this->obtener($id,$a);}catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}}
 public static function verificarCobro(PDO $db,array $data,$actorId,$turnId){if(!isset($data['borrador_id']))return null;$id=self::uuid($data['borrador_id']);$q=$db->prepare('SELECT * FROM borradores_venta WHERE id=? FOR UPDATE');$q->execute(array($id));$r=$q->fetch();if(!$r||(string)$r['usuario_id']!==(string)$actorId||(string)$r['turno_id']!==(string)$turnId)throw new HttpError('El ticket pendiente no pertenece a esta venta.',403);if($r['estado']!=='cobrando'||!isset($data['borrador_version'])||(string)$data['borrador_version']!==(string)$r['version'])throw new HttpError('El cobro pendiente cambió. Revisa su estado antes de continuar.',409);$stored=json_decode($r['cobro'],true);if(!self::same(self::datosCobro($data),$stored))throw new HttpError('Los datos del cobro preparado no coinciden.',409);return $id;}
}
